export class Job {
  constructor(scheduler, interval) {
    this.scheduler = scheduler;
    this.interval = interval;
    this.unit = null;
    this.tags = new Set();
    this.jobFunction = null;
  }

  get seconds() {
    this.unit = 'seconds';
    return this;
  }

  get minutes() {
    this.unit = 'minutes';
    return this;
  }

  tag(...tags) {
    for (const tag of tags) {
      this.tags.add(String(tag));
    }

    return this;
  }

  do(jobFunction) {
    this.jobFunction = jobFunction;
    this.scheduler.addJob(this);
    return this;
  }

  hasTag(tag) {
    return this.tags.has(tag);
  }
}

