function buildUsage(prog) {
  return `usage: ${prog} [-h] --a A --b B\n`;
}

function buildHelp(prog) {
  return `${buildUsage(prog)}\noptions:\n  -h, --help  show this help message and exit\n  --a A\n  --b B\n`;
}

function buildError(prog, detail) {
  return `${buildUsage(prog)}${prog}: error: ${detail}\n`;
}

function isNegativeIntegerToken(token) {
  return /^-\d(?:_?\d)*$/.test(token);
}

function isPythonIntLiteral(value) {
  return /^[+-]?\d(?:_?\d)*$/.test(value);
}

function parseIntegerValue(rawValue, option, prog) {
  if (!isPythonIntLiteral(rawValue)) {
    throw new ParserExit(
      2,
      buildError(prog, `argument ${option}: invalid int value: '${rawValue}'`),
      'stderr',
    );
  }

  return Number(rawValue.replace(/_/g, ''));
}

export class ParserExit extends Error {
  constructor(code, message, streamName) {
    super(message);
    this.code = code;
    this.message = message;
    this.streamName = streamName;
  }
}

export function parseMainArgs(argv, progPath) {
  const prog = basename(progPath);
  let aValue;
  let bValue;
  const unknownTokens = [];

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (token === '-h' || token === '--help' || token === '-h1') {
      throw new ParserExit(0, buildHelp(prog), 'stdout');
    }

    if (token.startsWith('-h=') || token.startsWith('--help=')) {
      throw new ParserExit(
        2,
        buildError(prog, `argument -h/--help: ignored explicit argument '${token.slice(token.indexOf('=') + 1)}'`),
        'stderr',
      );
    }

    if (token === '--a' || token === '--b') {
      const nextToken = argv[index + 1];

      if (
        typeof nextToken === 'undefined' ||
        (nextToken.startsWith('-') && !isNegativeIntegerToken(nextToken))
      ) {
        throw new ParserExit(
          2,
          buildError(prog, `argument ${token}: expected one argument`),
          'stderr',
        );
      }

      const parsedValue = parseIntegerValue(nextToken, token, prog);
      if (token === '--a') {
        aValue = parsedValue;
      } else {
        bValue = parsedValue;
      }

      index += 1;
      continue;
    }

    if (token.startsWith('--a=')) {
      aValue = parseIntegerValue(token.slice(4), '--a', prog);
      continue;
    }

    if (token.startsWith('--b=')) {
      bValue = parseIntegerValue(token.slice(4), '--b', prog);
      continue;
    }

    unknownTokens.push(token);
  }

