import { writeLine, writeText } from './lib/io.mjs';
import { ParserExit, parseMainArgs } from './lib/arg_parser.mjs';
import * as schedule from './lib/schedule/index.mjs';

function basename(filePath) {
  if (!filePath) {
    return '';
  }

  const parts = filePath.split(/[\\/]/).filter(Boolean);
  return parts.length > 0 ? parts[parts.length - 1] : filePath;
}

export function main(argv = process.argv.slice(2), io = { stdout: process.stdout, stderr: process.stderr }, progPath = process.argv[1]) {
  let args;

  try {
    args = parseMainArgs(argv, progPath);
  } catch (error) {
    if (error instanceof ParserExit) {
      const stream = error.streamName === 'stdout' ? io.stdout : io.stderr;
      writeText(stream, error.message);
      return error.code;
    }

    throw error;
  }

  schedule.clear();

  let jobsCreated = 0;

  for (let index = 0; index < args.a; index += 1) {
    schedule.every(1).seconds.tag('group1').do(() => null);
    jobsCreated += 1;
  }
  writeLine(io.stdout, jobsCreated);

  for (let index = 0; index < args.b; index += 1) {
    schedule.every(1).minutes.tag('group2').do(() => null);
    jobsCreated += 1;
  }
  writeLine(io.stdout, jobsCreated);

  const group1Jobs = schedule.getJobs('group1');
  writeLine(io.stdout, group1Jobs.length);

  const group2Jobs = schedule.getJobs('group2');
  writeLine(io.stdout, group2Jobs.length);

  const allJobs = schedule.getJobs();
  writeLine(io.stdout, allJobs.length);

  schedule.clear('group1');
  writeLine(io.stdout, schedule.getJobs().length);

  schedule.clear('group2');
  writeLine(io.stdout, schedule.getJobs().length);

  for (let index = 0; index < args.a + args.b; index += 1) {
    schedule.every(1).seconds.do(() => null);
  }
  writeLine(io.stdout, schedule.getJobs().length);

  return 0;
}

const isDirectRun = process.argv[1] && import.meta.url.endsWith(`/${basename(process.argv[1])}`);

if (isDirectRun) {
  process.exitCode = main();
}

